import { json, redirect } from "@remix-run/cloudflare";
import { getReferralById } from "~/services/referral";
import type { LoaderFunction } from "@remix-run/cloudflare";

export const loader: LoaderFunction = async ({ params, context: { db } }) => {
  const { id } = params;

  // Check if id is provided
  if (!id) {
    throw new Response("Referral ID is required", { status: 400 });
  }

  // Fetch referral from the database using the getReferralById service
  const referral = await getReferralById(db, id);

  // If no referral is found, return a 404 status
  if (!referral) {
    throw new Response("Referral not found", { status: 404 });
  }

  // If the referral is archived, redirect to the archive page
  if (referral.archived_at) {
    return redirect(`/referrals/archived/${id}`);
  }

  return json(referral);
};
```

### 2. Service Call (`services/referral.ts`)

The `getReferralById` function, called within the `loader` function, interacts with the database to retrieve the specific referral data.

**File:** `services/referral.ts`
**Lines:** 15-20

```typescript
import { and, eq, isNull } from "drizzle-orm";
import { referrals } from "~/database/schema";

export const getReferralById = async (db, id) => {
  try {
    // Query the database for a referral with the given id and where archived_at is null (not archived)
    const referral = await db.query.referrals.findFirst({
      where: and(eq(referrals.id, id), isNull(referrals.archived_at)),
    });

    return referral;
  } catch (error) {
    console.error(`Error fetching referral with ID ${id}:`, error.message);
    throw new Error(`Database error: ${error.message}`);
  }
};
```

